const raw = $json.choices?.[0]?.message?.content ?? '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/^```json\s*/i, '').replace(/```$/, '').trim()); }
catch { parsed = { problem_statement: raw, research_questions: [raw], search_queries: [raw] }; }
return [{ json: { topic: $('Research Input (edit topic)').first().json.topic, depth: $('Research Input (edit topic)').first().json.depth, problem_statement: parsed.problem_statement || '', research_questions: parsed.research_questions || [], search_queries: parsed.search_queries || [] } }];

const plan = $('Parse Problem & Research Plan').first().json;
const results = ($json.results || []).map((r, i) => ({ id: `S${i+1}`, title: r.title || 'Untitled', url: r.url || '', content: r.content || r.raw_content || '', score: r.score ?? null }));
return [{ json: { ...plan, sources: results } }];

const base = $('Attach Feasibility Audit').first().json;
const report = $json.choices?.[0]?.message?.content || 'No proposal generated.';
return [{
  json: {
    topic: base.topic,
    depth: base.depth,
    problem_statement: base.problem_statement,
    research_questions: base.research_questions,
    search_queries: base.search_queries,
    sources: base.sources,
    analysis: base.analysis,
    fact_check: base.fact_check,
    report_markdown: report,
    status: 'Verified Research Dossier',
    timestamp: new Date().toISOString()
  }
}];
